class Solution
{
    vector<int> parent, rankValue;
    int find(int x)
    {
        if (parent[x] != x)
        {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }
    bool unite(int a, int b)
    {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (rankValue[a] < rankValue[b]) swap(a, b);
        parent[b] = a;
        if (rankValue[a] == rankValue[b]) ++rankValue[a];
        return true;
    }
public:
    vector<int> numIslands2(int m, int n, vector<vector<int>>& positions) {
        parent.assign(m * n, -1);
        rankValue.assign(m * n, 0);
        vector<int> answer;
        int islands = 0;
        const int dr[] = {1, -1, 0, 0};
        const int dc[] = {0, 0, 1, -1};
        for (const auto& p : positions) {
            int r = p[0], c = p[1], id = r * n + c;
            if (parent[id] == -1)
            {
                parent[id] = id;
                ++islands;
                for (int d = 0; d < 4; ++d)
                {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n)
                    {
                        int neighbor = nr * n + nc;
                        if (parent[neighbor] != -1 && unite(id, neighbor))
                        {
                            --islands;
                        }
                    }
                }
            }
            answer.push_back(islands);
        }
        return answer;
    }
};
